import{_ as a}from"./chunks/op_logic.CwvdS02y.js";import{_ as n,o as p,a as l,b as c}from"./app.BGziXukh.js";const t="/ascendc.github.io/assets/vec_op_impl_c_api.DIKPbxWE.svg",e="/ascendc.github.io/assets/add_op_c_api.BoSCWQnj.svg",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/operator_practice"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矢量编程（C API）","link":"/guide/operator_practice/simd_operator_impl/vector_programming_c_api/vector_programming_c_api"},{"text":"基础矢量算子","link":"/guide/operator_practice/simd_operator_impl/vector_programming_c_api/basic_vector_operator"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/vector_programming_c_api/basic_vector_operator.md","filePath":"guide/operator_practice/simd_operator_impl/vector_programming_c_api/basic_vector_operator.md","outlineHeaders":[{"level":2,"title":"算子分析","slug":"算子分析","link":"#算子分析"},{"level":2,"title":"核函数（Kernel）定义","slug":"核函数（Kernel）定义","link":"#核函数（Kernel）定义"},{"level":2,"title":"算子类实现","slug":"算子类实现","link":"#算子类实现"},{"level":2,"title":"Reg矢量函数实现","slug":"Reg矢量函数实现","link":"#Reg矢量函数实现"}],"lastUpdated":1795433433000}'),o={name:"guide/operator_practice/simd_operator_impl/vector_programming_c_api/basic_vector_operator.md"};function _(i,s,r,d,w,h){return p(),l("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>基础矢量算子</h1><p>基于Ascend C的C API方式实现基础矢量算子核函数（Kernel）的流程如下图所示。</p><p><strong>图1</strong> 矢量算子核函数（Kernel）实现流程</p><p><img src="'+t+`" alt title="矢量算子核函数（Kernel）实现流程"></p><ul><li>算子分析：分析算子的数学表达式、输入、输出以及计算逻辑的实现，明确需要调用的C API。</li><li>核函数（Kernel）定义：定义Ascend C算子入口函数。</li><li>通过C API和显式同步实现算子类：完成核函数（Kernel）的内部实现，包括3个基本任务：CopyIn，Compute，CopyOut。</li></ul><p>下文以输入为half数据类型且shape的最后一维为32Bytes对齐、在单核上运行的、一次完成计算的Add算子为例，对上述步骤进行详细介绍。</p><h2 id="算子分析">算子分析<a id="basic_vector_analysis"></a><a class="header-anchor" href="#算子分析">​</a></h2><p>算子分析具体步骤如下：</p><ol><li><p>明确算子的数学表达式及计算逻辑。</p><p>Add算子的数学表达式为：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>z = x + y
</code></pre></div><p>计算逻辑是：C API提供的<a href="../../../../api/SIMD-API/c_api/reg_compute/reg_arith/asc_add.html">矢量计算接口</a>通过寄存器加载、计算和存储接口访问UB中的操作元素，输入数据需要先从外部存储（Global Memory）搬运到Unified Buffer（UB），然后使用计算接口完成两个输入参数相加，得到最终结果，再搬出到外部存储上。Ascend C Add算子的计算逻辑如下图所示。</p><p><strong>图2</strong> 算子计算逻辑<br><img src="`+a+`" alt title="算子计算逻辑"></p></li><li><p>明确输入和输出。</p><ul><li><p>Add算子有两个输入：x与y；输出为z。</p></li><li><p>本样例中算子的输入支持的数据类型为half（float16），算子输出的数据类型与输入的数据类型相同。</p></li><li><p>算子输入支持的shape为（1，2048），输出shape与输入shape相同。</p></li><li><p>算子输入支持的<a href="../../../technical_appendix/concepts_and_terms/neural_networks_and_operators/data_layout.html">format</a>为：ND。</p></li></ul></li><li><p>确定核函数（Kernel）名称和参数。</p><ul><li><p>您可以自定义核函数（Kernel）名称，本样例中核函数（Kernel）命名为vector_add_custom。</p></li><li><p>根据对算子输入输出的分析，确定核函数（Kernel）有3个参数x，y，z；x，y为输入在Global Memory上的内存地址，z为输出在Global Memory上的内存地址。</p></li></ul></li><li><p>确定算子实现所需接口。</p><ul><li><p>实现涉及外部存储和内部存储间的数据搬运，查看Ascend C API参考中的数据搬运接口，需要使用<a href="../../../../api/SIMD-API/c_api/vector_datamove/asc_copy_gm2ub_align/asc_copy_gm2ub_align_arch_3510.html">asc_copy_gm2ub_align</a>和<a href="../../../../api/SIMD-API/c_api/vector_datamove/asc_copy_ub2gm_align/asc_copy_ub2gm_align_arch_3510.html">asc_copy_ub2gm_align</a>来实现数据搬运。</p></li><li><p>本样例只涉及矢量计算的加法操作，查看Ascend C API参考中的<a href="../../../../api/SIMD-API/c_api/reg_compute/reg_compute.html">矢量计算</a>接口，初步分析可使用基础算术Add接口<a href="../../../../api/SIMD-API/c_api/reg_compute/reg_arith/asc_add.html">asc_add</a>实现x+y。</p></li><li><p>使用显式声明的UB数组管理计算中使用的数据，通过<a href="../../../../api/SIMD-API/c_api/sync/intra_core_sync/asc_sync_notify.html">asc_sync_notify</a>、<a href="../../../../api/SIMD-API/c_api/sync/intra_core_sync/asc_sync_wait.html">asc_sync_wait</a>等接口完成跨流水同步。</p></li></ul></li></ol><p>通过以上分析，得到Ascend C Add算子的设计规格如下：</p><ul><li><p>算子类型（OpType）：Add</p></li><li><p>算子输入输出：</p><p><strong>表1</strong> Add算子输入输出规格</p><table><thead><tr><th>name</th><th>shape</th><th>data type</th><th>format</th></tr></thead><tbody><tr><td>x（输入）</td><td>(1, 2048)</td><td>half</td><td>ND</td></tr><tr><td>y（输入）</td><td>(1, 2048)</td><td>half</td><td>ND</td></tr><tr><td>z（输出）</td><td>(1, 2048)</td><td>half</td><td>ND</td></tr></tbody></table></li><li><p>核函数（Kernel）名称：vector_add_custom</p></li><li><p>使用的主要接口：</p><ul><li><p>asc_copy_gm2ub_align、asc_copy_ub2gm_align：数据搬移接口</p></li><li><p>asc_add：矢量基础算术接口</p></li><li><p>asc_sync_notify、asc_sync_wait等接口：跨流水同步接口</p></li><li><p>asc_init：核内控制状态初始化接口</p></li><li><p>asc_sync：核内全流水同步接口</p></li></ul></li><li><p>算子实现文件名称：vector_add.asc</p></li></ul><h2 id="核函数（Kernel）定义">核函数（Kernel）定义<a class="header-anchor" href="#核函数（Kernel）定义">​</a></h2><p>根据<a href="../../../programming_guide/programming_model/ai_core_simd_programming/kernel_function.html">核函数（Kernel）</a>中介绍的规则进行核函数（Kernel）的定义。</p><ol><li><p>函数原型定义</p><p>本样例中，函数名为vector_add_custom（核函数（Kernel）名称可自定义），根据<a href="#basic_vector_analysis">算子分析</a>中对算子输入输出的分析，确定有3个参数x，y，z，其中x，y为输入内存，z为输出内存。根据<a href="../../../programming_guide/programming_model/ai_core_simd_programming/kernel_function.html#zh-cn_topic_0000001447989210_section1915102519220">核函数（Kernel）</a>的规则介绍，函数原型定义如下所示：使用__global__函数类型限定符标识它是一个核函数（Kernel），可以被&lt;&lt;&lt;&gt;&gt;&gt;调用；使用__vector__函数类型限定符标识该核函数（Kernel）在设备端aicore的Vector Core上执行。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">vector_add_custom</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
<span class="p">{</span>
<span class="p">}</span>
</code></pre></div></li><li><p>调用算子类的Init和Process函数。</p><p>算子类的Init函数，完成内存初始化相关工作，Process函数完成算子实现的核心逻辑，具体介绍参见<a href="#basic_vector_class">算子类实现</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">vector_add_custom</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc_init</span><span class="p">();</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">xLocal</span><span class="p">[</span><span class="n">TOTAL_LENGTH</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">yLocal</span><span class="p">[</span><span class="n">TOTAL_LENGTH</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">zLocal</span><span class="p">[</span><span class="n">TOTAL_LENGTH</span><span class="p">];</span>
<span class="w">    </span><span class="n">KernelAdd</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">zLocal</span><span class="p">);</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Process</span><span class="p">();</span>
<span class="w">    </span><span class="n">asc_sync</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div></li><li><p>根据<a href="../../../programming_guide/programming_model/ai_core_simd_programming/kernel_function.html#zh-cn_topic_0000001447989210_section1915102519220">核函数（Kernel）定义和调用</a>章节，调用核函数（Kernel）时，除了需要传入参数x，y，z，还需要传入numBlocks（核函数（Kernel）执行的核数）、动态UB大小（无动态UB需求时设置为0）、stream（应用程序中维护异步操作执行顺序的stream）来规定核函数（Kernel）的执行配置。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">vector_add_custom</span><span class="o">&lt;&lt;&lt;</span><span class="n">numBlocks</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">xDevice</span><span class="p">,</span><span class="w"> </span><span class="n">yDevice</span><span class="p">,</span><span class="w"> </span><span class="n">zDevice</span><span class="p">);</span>
</code></pre></div></li></ol><h2 id="算子类实现">算子类实现<a id="basic_vector_class"></a><a class="header-anchor" href="#算子类实现">​</a></h2><p>根据上一节介绍，核函数（Kernel）中会调用算子类的Init和Process函数，本节具体讲解如何通过C API和显式同步实现算子类。</p><p>通过C API和显式同步对Add算子的实现流程进行设计的思路如下，设计完成后得到的Add算子实现流程图参见<a href="#basic_vector_stages">图3 Add算子实现流程</a>：</p><ul><li>Add算子的实现流程分为3个基本任务：CopyIn，Compute，CopyOut。CopyIn任务负责将Global Memory上的输入指针xGm和yGm搬运至Local Memory，分别存储在xLocal，yLocal，Compute任务负责对xLocal，yLocal执行加法操作，计算结果存储在zLocal中，CopyOut任务负责将输出数据从zLocal搬运至Global Memory上的输出指针zGm中。</li><li>CopyIn，Compute任务间通过MTE2到V的notify/wait事件进行同步，Compute，CopyOut任务间通过V到MTE3的notify/wait事件进行同步。</li><li>任务间交互使用到的内存、临时变量的内存使用显式声明的UB数组进行管理，算子类保存其地址。</li></ul><p><strong>图3</strong> Add算子实现流程<a id="basic_vector_stages"></a></p><p><img src="`+e+`" alt="Add算子实现流程"></p><p>算子类中主要实现上述流程，包含对外开放的初始化Init函数和核心处理函数Process，Process函数中会对上图中的三个基本任务进行调用；同时包括一些算子实现中会用到的私有成员，比如上图中的GM指针（xGm、yGm、zGm）和UB指针（xLocal、yLocal、zLocal）等。KernelAdd算子类具体成员如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;cstdint&gt;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;c_api/asc_simd.h&quot;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">TOTAL_LENGTH</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">2048</span><span class="p">;</span><span class="w">  </span><span class="c1">// 数据总长</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">TOTAL_BYTES</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">TOTAL_LENGTH</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">);</span><span class="w">  </span><span class="c1">// 搬运字节数</span>

<span class="k">class</span><span class="w"> </span><span class="nc">KernelAdd</span><span class="w"> </span><span class="p">{</span>
<span class="k">public</span><span class="o">:</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">KernelAdd</span><span class="p">()</span><span class="w"> </span><span class="p">{}</span>
<span class="w">    </span><span class="c1">// 初始化函数，完成内存地址初始化相关操作</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Init</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">,</span>
<span class="w">        </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">xBuffer</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">yBuffer</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">zBuffer</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 核心处理函数，实现算子逻辑，调用私有成员函数CopyIn、Compute、CopyOut完成矢量算子的三级流水操作</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Process</span><span class="p">()</span>
<span class="w">    </span><span class="p">{</span>
<span class="w">        </span><span class="n">CopyIn</span><span class="p">();</span>
<span class="w">        </span><span class="n">Compute</span><span class="p">();</span>
<span class="w">        </span><span class="n">CopyOut</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span>

<span class="k">private</span><span class="o">:</span>
<span class="w">    </span><span class="c1">// 搬入函数，完成CopyIn阶段的处理，被核心Process函数调用</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CopyIn</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// 计算函数，完成Compute阶段的处理，被核心Process函数调用</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Compute</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// 搬出函数，完成CopyOut阶段的处理，被核心Process函数调用</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CopyOut</span><span class="p">();</span>

<span class="k">private</span><span class="o">:</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">xGm</span><span class="p">;</span><span class="w">  </span><span class="c1">// 输入输出Global Memory内存地址，其中xGm、yGm为输入，zGm为输出</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">yGm</span><span class="p">;</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">zGm</span><span class="p">;</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">xLocal</span><span class="p">;</span><span class="w">  </span><span class="c1">// 输入x的UB数组地址</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">yLocal</span><span class="p">;</span><span class="w">  </span><span class="c1">// 输入y的UB数组地址</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">zLocal</span><span class="p">;</span><span class="w">  </span><span class="c1">// 输出z的UB数组地址</span>
<span class="p">};</span>
</code></pre></div><p>初始化函数主要完成以下内容：</p><ul><li><p>设置输入输出指针的Global Memory内存地址。</p><p>本样例中的分配方案是：数据整体长度TOTAL_LENGTH为1 * 2048，通过指针转换设定该核上Global Memory的起始地址，并使用TOTAL_LENGTH记录数据长度。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">xGm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*&gt;</span><span class="p">(</span><span class="n">x</span><span class="p">);</span>
</code></pre></div></li><li><p>通过核函数中显式声明的UB数组为输入输出分配内存，并在Init中保存其地址。</p><p>比如，保存输入x的UB数组地址，可以通过如下代码段实现：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">xLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">xBuffer</span><span class="p">;</span>
</code></pre></div></li></ul><p>具体的初始化函数代码如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">KernelAdd</span><span class="o">::</span><span class="n">Init</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">,</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">xBuffer</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">yBuffer</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">zBuffer</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 设置Global Memory的起始地址以及长度，长度由TOTAL_LENGTH记录</span>
<span class="w">    </span><span class="n">xGm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*&gt;</span><span class="p">(</span><span class="n">x</span><span class="p">);</span>
<span class="w">    </span><span class="n">yGm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*&gt;</span><span class="p">(</span><span class="n">y</span><span class="p">);</span>
<span class="w">    </span><span class="n">zGm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*&gt;</span><span class="p">(</span><span class="n">z</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 保存核函数中已分配的输入输出UB数组地址</span>
<span class="w">    </span><span class="n">xLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">xBuffer</span><span class="p">;</span>
<span class="w">    </span><span class="n">yLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">yBuffer</span><span class="p">;</span>
<span class="w">    </span><span class="n">zLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">zBuffer</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div><p>通过C API和显式同步，将核函数（Kernel）的实现分为3个基本任务：CopyIn，Compute，CopyOut。再根据上面的算法分析，将整个计算拆分成三个Stage，用户单独编写每个Stage的代码，三阶段流程示意图参见<a href="#basic_vector_stages">图3</a>，具体流程如下：</p><ol><li><p>Stage1：CopyIn实现。</p><ol><li>使用<a href="../../../../api/SIMD-API/c_api/vector_datamove/asc_copy_gm2ub_align/asc_copy_gm2ub_align_arch_3510.html">asc_copy_gm2ub_align</a>接口将GM数据拷贝到UB数组。</li><li>使用asc_sync_notify、asc_sync_wait建立MTE2到V的依赖，保证搬入完成后才能计算。</li></ol><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">KernelAdd</span><span class="o">::</span><span class="n">CopyIn</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 将Global Memory数据拷贝到UB数组</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xGm</span><span class="p">,</span><span class="w"> </span><span class="n">TOTAL_BYTES</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yGm</span><span class="p">,</span><span class="w"> </span><span class="n">TOTAL_BYTES</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 等待输入数据搬入完成</span>
<span class="w">    </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></li><li><p>Stage2：Compute实现。</p><ol><li>使用已完成搬入的UB输入数组。</li><li>使用C API接口<a href="../../../../api/SIMD-API/c_api/reg_compute/reg_arith/asc_add.html">asc_add</a>完成矢量计算。</li><li>使用asc_sync_notify、asc_sync_wait建立V到MTE3的依赖，保证计算完成后才能搬出。</li><li>输入UB数组在本次计算后不再使用，其空间保留到核函数结束，无需调用释放接口。</li></ol><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">KernelAdd</span><span class="o">::</span><span class="n">Compute</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 调用Add算子进行计算</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">AddVF</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">TOTAL_LENGTH</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 等待计算完成后再搬出结果</span>
<span class="w">    </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></li><li><p>Stage3：CopyOut实现。</p><ol><li>使用已完成计算的UB输出数组。</li><li>使用<a href="../../../../api/SIMD-API/c_api/vector_datamove/asc_copy_ub2gm_align/asc_copy_ub2gm_align_arch_3510.html">asc_copy_ub2gm_align</a>接口将UB数据拷贝到GM上。</li><li>核函数退出前使用asc_sync等待搬出完成，再结束UB数组的使用。</li></ol><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">KernelAdd</span><span class="o">::</span><span class="n">CopyOut</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 将计算结果从UB数组拷贝到Global Memory</span>
<span class="w">    </span><span class="n">asc_copy_ub2gm_align</span><span class="p">(</span><span class="n">zGm</span><span class="p">,</span><span class="w"> </span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">TOTAL_BYTES</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 核函数中在Process返回后调用asc_sync，等待搬出完成</span>
<span class="p">}</span>
</code></pre></div></li></ol><h2 id="Reg矢量函数实现">Reg矢量函数实现<a class="header-anchor" href="#Reg矢量函数实现">​</a></h2><p>上述计算通过asc_vf_call调用以下矢量函数。实际源文件中将该定义放在调用位置之前；输入UB数组须按完整VL（256字节）向上对齐预留，搬运仍只处理实际数据长度。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;c_api/asc_simd.h&quot;</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">AddVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">remain</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">count</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">count</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">T</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span>
<span class="w">        </span><span class="k">if</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="p">(</span><span class="k">sizeof</span><span class="p">(</span><span class="n">T</span><span class="p">)</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">2</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b16</span><span class="p">(</span><span class="n">remain</span><span class="p">);</span>
<span class="w">        </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b32</span><span class="p">(</span><span class="n">remain</span><span class="p">);</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">        </span><span class="k">auto</span><span class="w"> </span><span class="n">a</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="p">);</span>
<span class="w">        </span><span class="k">auto</span><span class="w"> </span><span class="n">b</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">y</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="p">);</span>
<span class="w">        </span><span class="k">auto</span><span class="w"> </span><span class="n">result</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_add</span><span class="p">(</span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="p">,</span><span class="w"> </span><span class="n">result</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const u=n(o,[["render",_]]);export{m as __pageData,u as default};
